def canonicalModelOf (H : Hilbert ℕ) [H.Consistent] [H.IncludeEFQ] : Kripke.Model where
  toFrame := Kripke.canonicalFrameOf H
  Val := ⟨λ t a => (atom a) ∈ t.tableau.1, by aesop⟩

