  obtain ⟨φ, hyp, nhzp⟩ := Set.not_subset.mp nRyz;
  intro ψ hqz;
  have : ψ ➝ φ ∉ x.tableau.1 := by
    by_contra hqpx;
    have hqpz : ψ ➝ φ ∈ z.tableau.1 := by aesop;
    have : φ ∈ z.tableau.1 := mdp₁_mem hqz hqpz;
