lemma sound_hilbert_of_frameclass (definedBy : C.DefinedBy T) : (⟨������ ∪ T⟩ : Hilbert ℕ) ⊢! φ → C ⊧ φ := by
  intro hφ F hF;
  induction hφ using Hilbert.Deduction.rec! with
