  World := SCT H
  Rel t₁ t₂ := t₁.tableau.1 ⊆ t₂.tableau.1
  rel_po := {
    refl := by simp;
    trans := fun x y z Sxy Syz => Set.Subset.trans Sxy Syz
    antisymm := fun x y Sxy Syx => equality_of₁ (Set.Subset.antisymm Sxy Syx)
  }

