private lemma euclidean_of_subset_lem_frameTheorems : (������ ⊆ F.theorems) → Euclidean F := by
  simp [Frame.theorems];
  rintro h x y z Rxy Rxz;
  let M : Kripke.Model := ⟨F, λ v _ => z ≺ v, by simp; intro w v _ _; trans w <;> assumption⟩;
  suffices Kripke.Satisfies M y (atom default) by simpa [Kripke.Satisfies] using this;
  apply M.Val.hereditary Rxy;
  have := @h (atom default) M.Val x;
  simp only [Axioms.LEM, Semantics.Realize, Kripke.Satisfies, or_iff_not_imp_right] at this;
  apply this;
  push_neg;
  use z;
  constructor;
  . exact Rxz;
  . simp [Kripke.Satisfies, M];

lemma weaker_than_of_subset_axiomset {H₁ H₂ : Hilbert α} (hSubset : H₁.axioms ⊆ H₂.axioms := by aesop) : H₁ ≤ₛ H₂ := by
  apply weaker_than_of_subset_axiomset';
  intro φ hp;
  apply eaxm! $ hSubset hp;

lemma weaker_than_of_subset_axiomset' {H₁ H₂ : Hilbert α} (hMaxm : ∀ {φ : Formula α}, φ ∈ H₁.axioms → H₂ ⊢! φ)
  : H₁ ≤ₛ H₂ := by
  apply System.weakerThan_iff.mpr;
  intro φ h;
  induction h using Deduction.rec! with
  | eaxm hp => apply hMaxm hp;
  | mdp ihpq ihp => exact ihpq ⨀ ihp;
  | _ => simp;

